export interface ProductPricingValues {
    price?: number | null;
    purchasePrice?: number | null;
    costPrice?: number | null;
    markupPercent?: number | null;
    requiresPriceApproval?: boolean;
}

export function getMissingProductPrices(product: ProductPricingValues): string[] {
    const positive = (value: number | null | undefined) => value != null && Number.isFinite(value) && value > 0;
    return [
        !positive(product.purchasePrice) && "закупочная цена",
        !positive(product.costPrice) && "себестоимость",
        (product.markupPercent == null || !Number.isFinite(product.markupPercent) || product.markupPercent < 0) && "надбавка",
        !positive(product.price) && "конечная цена",
    ].filter((value): value is string => Boolean(value));
}

export const isProductPricingInactive = (product: ProductPricingValues): boolean =>
    Boolean(product.requiresPriceApproval) || getMissingProductPrices(product).length > 0;
