import React, {useState} from "react";
import CatalogCostCard from "../costing/CatalogCostCard";
import {ReceiptPricingProductStage} from "../costing/ReceiptPricingPage";
import {Link, matchPath, useLocation, useParams} from "react-router-dom";
import {Alert, Button, Chip} from "@mui/material";
import ArrowBackRoundedIcon from "@mui/icons-material/ArrowBackRounded";
import ArrowForwardRoundedIcon from "@mui/icons-material/ArrowForwardRounded";
import EditOutlinedIcon from "@mui/icons-material/EditOutlined";
import ContentCopyOutlinedIcon from "@mui/icons-material/ContentCopyOutlined";
import Inventory2OutlinedIcon from "@mui/icons-material/Inventory2Outlined";
import AddTaskRoundedIcon from "@mui/icons-material/AddTaskRounded";
import QrCode2RoundedIcon from "@mui/icons-material/QrCode2Rounded";
import PhotoCameraOutlinedIcon from "@mui/icons-material/PhotoCameraOutlined";
import SubjectRoundedIcon from "@mui/icons-material/SubjectRounded";
import TuneRoundedIcon from "@mui/icons-material/TuneRounded";
import Loader from "../../ui/loader/loader";
import {EmptyState, MainDiv} from "../../ui/commonStyled/commonStyled";
import {useGetProductByIdQuery} from "./productsApi";
import {useGetCategoryByIdQuery} from "../categories/categoriesApi";
import {IProduct} from "../../models/product";
import {useTranslation} from "../../i18n";
import {productDetailsMessages} from "./productDetailsMessages";
import {getMissingProductPrices, isProductPricingInactive} from "./productPricing";
import "./productDetails.css";

interface ProductDetailsProps {
    isOrder?: boolean;
}

interface ProductDetailsViewProps extends ProductDetailsProps {
    product: IProduct;
    categoryName?: string;
}

const ProductPlaceholder = () => (
    <svg className="pd-placeholder-art" viewBox="0 0 240 220" fill="none" aria-hidden="true">
        <ellipse cx="120" cy="190" rx="74" ry="13" fill="currentColor" opacity=".07"/>
        <path d="M45 76 120 35l75 41v85l-75 42-75-42V76Z" fill="var(--pd-box-left)"/>
        <path d="m120 118 75-42v85l-75 42v-85Z" fill="var(--pd-box-right)"/>
        <path d="m45 76 75-41 75 41-75 42-75-42Z" fill="var(--pd-box-top)"/>
        <path d="m91 51 76 42v31l-20 11v-31L71 62l20-11Z" fill="var(--color-primary)" opacity=".78"/>
        <path d="m64 129 24 13m-24-1 15 8" stroke="var(--color-muted)" strokeWidth="4" strokeLinecap="round" opacity=".4"/>
        <path d="m120 118 75-42M120 118v85" stroke="var(--color-surface)" strokeWidth="2" opacity=".5"/>
    </svg>
);

export const ProductDetailsView = ({product, categoryName, isOrder = false}: ProductDetailsViewProps) => {
    const {t, locale, language} = useTranslation();
    const messages = productDetailsMessages[language];
    const {state} = useLocation();
    const returnTo = typeof state?.returnTo === "string" && matchPath("/ordersManagement/:id", state.returnTo)
        ? state.returnTo : "/ordersManagement";
    const [failedImage, setFailedImage] = useState<string>();
    const characteristics = product.characteristics ?? [];
    const fields = Object.entries(product.fields ?? {});
    const resolvedCategory = categoryName || product.categoryName || product.category?.name || `${t("Категория")} #${product.categoryId}`;
    const hasImage = Boolean(product.imageName && product.hasCustomImage !== false && product.imageName !== failedImage);
    const price = product.price.toLocaleString(locale, {minimumFractionDigits: 2, maximumFractionDigits: 2});
    const editUrl = `/productsManagement/editProduct/${product.id}`;
    const missingPrices = getMissingProductPrices(product);
    const pricingInactive = isProductPricingInactive(product);
    const money = (value: number | null | undefined) => value == null || value <= 0 ? "Не указана" : `${value.toLocaleString(locale, {maximumFractionDigits: 6})} BYN`;

    return (
        <MainDiv className="product-detail">
            <div className="pd-page-heading">
                <span className="pd-eyebrow">{messages.card}</span>
                <Link className="pd-back-link" replace to="/productsManagement">
                    <ArrowBackRoundedIcon/>{messages.back}
                </Link>
            </div>

            <section className="pd-hero" aria-labelledby="pd-product-name">
                <div className="pd-gallery">
                    <div className="pd-gallery-label"><PhotoCameraOutlinedIcon/>{messages.photo}</div>
                    <div className="pd-image-stage">
                        {hasImage ? (
                            <img className="pd-product-image" src={product.imageName} alt={product.name}
                                 onError={() => setFailedImage(product.imageName)}/>
                        ) : (
                            <div className="pd-image-placeholder">
                                <ProductPlaceholder/>
                                <strong>{messages.noPhoto}</strong>
                                <span>{messages.photoHint}</span>
                            </div>
                        )}
                    </div>
                    <div className="pd-gallery-footer">
                        <span>{hasImage ? messages.imageCaption : messages.imageMissing}</span>
                        {!isOrder && <Link to={editUrl}><EditOutlinedIcon/>{hasImage ? messages.change : messages.addPhoto}</Link>}
                    </div>
                </div>

                <div className="pd-summary">
                    <div className="pd-product-category">
                        <span className="pd-category-dot" aria-hidden="true"/>
                        <Link to={`/productCategories/hierarchy/${product.categoryId}`}>{resolvedCategory}</Link>
                    </div>
                    <h1 id="pd-product-name">{product.name}</h1>
                    <div className="pd-identifiers">
                        <span className="pd-product-id">ID <strong>#{product.id}</strong></span>
                        <span className="pd-identifier-divider" aria-hidden="true"/>
                        <span className="pd-gtin"><QrCode2RoundedIcon/><span>GTIN <strong>{product.gtin || "—"}</strong></span></span>
                    </div>

                    <Chip className="pd-pricing-status" size="small" color={pricingInactive ? "warning" : "success"} label={pricingInactive ? "Неактивна для заказов" : "Активна для заказов"}/>
                    <div className={`pd-price-panel${pricingInactive ? " pd-price-panel-incomplete" : ""}`}>
                        <div className="pd-price-heading"><span>{messages.price}</span><span className="pd-price-currency">BYN</span></div>
                        <div className="pd-price"><strong>{product.price > 0 ? price : "Не указана"}</strong>{product.price > 0 && <span>BYN</span>}</div>
                        <dl className="pd-price-breakdown">
                            <div><dt>Закупочная цена</dt><dd>{money(product.purchasePrice)}</dd></div>
                            <div><dt>Себестоимость</dt><dd>{money(product.costPrice)}</dd></div>
                            <div><dt>Надбавка</dt><dd>{product.markupPercent == null || product.markupPercent < 0 ? "Не указана" : `${product.markupPercent.toLocaleString(locale)} %`}</dd></div>
                        </dl>
                    </div>
                    {pricingInactive && <Alert severity="warning">Карточка неактивна для заказов. {missingPrices.length ? `Нужно заполнить: ${missingPrices.join(", ")}. Откройте редактирование карточки или утвердите цены в разделе ценообразования.` : "Цены ожидают утверждения в разделе ценообразования."}</Alert>}

                    <div className="pd-actions">
                        {isOrder ? (
                            <Button className="pd-edit-button" component={Link} replace to={returnTo} variant="contained" disableElevation
                                    startIcon={<ArrowBackRoundedIcon/>}>{messages.backToOrder}</Button>
                        ) : (
                            <>
                                <Button className="pd-edit-button" component={Link} to={editUrl} variant="contained"
                                        disableElevation startIcon={<EditOutlinedIcon/>}>{messages.edit}</Button>
                                <Button className="pd-copy-button" component={Link} to={`/productsManagement/copyProduct/${product.id}`}
                                        variant="outlined" startIcon={<ContentCopyOutlinedIcon/>}>{messages.duplicate}</Button>
                            </>
                        )}
                    </div>
                    <div className="pd-secondary-actions">
                        <Link to="/stockManagement"><Inventory2OutlinedIcon/>{messages.stock}<ArrowForwardRoundedIcon className="pd-link-arrow"/></Link>
                        <Link to={`/collaboration?kind=product&id=${encodeURIComponent(String(product.id))}&view=tasks`}>
                            <AddTaskRoundedIcon/>{messages.task}<ArrowForwardRoundedIcon className="pd-link-arrow"/>
                        </Link>
                    </div>
                </div>
            </section>

            <div className="pd-information">
                <section className="pd-section pd-description" aria-labelledby="pd-description-heading">
                    <div className="pd-section-heading">
                        <SubjectRoundedIcon/>
                        <h2 id="pd-description-heading">{t("Описание")}</h2>
                    </div>
                    <div className={`pd-description-text${!product.description ? " pd-muted" : ""}`}>
                        {product.description || messages.noDescription}
                    </div>
                    <div className="pd-description-category">
                        <span>{t("Категория")}</span>
                        <Link to={`/productCategories/hierarchy/${product.categoryId}`}>{resolvedCategory}<ArrowForwardRoundedIcon/></Link>
                    </div>
                </section>

                <section className="pd-section pd-specifications" aria-labelledby="pd-specifications-heading">
                    <div className="pd-section-heading">
                        <TuneRoundedIcon/>
                        <h2 id="pd-specifications-heading">{t("Characteristics")}</h2>
                        <span className="pd-count">{characteristics.length + fields.length}</span>
                    </div>
                    {characteristics.length > 0 && (
                        <dl className="pd-spec-list">
                            {characteristics.map((characteristic, index) => (
                                <div className="pd-spec-row" key={`${characteristic.name}-${index}`}>
                                    <dt>{characteristic.name}</dt><dd>{characteristic.value || t("Нет данных")}</dd>
                                </div>
                            ))}
                        </dl>
                    )}
                    {fields.length > 0 && (
                        <>
                            <h3 className="pd-fields-heading">{messages.additionalFields}</h3>
                            <dl className="pd-spec-list">
                                {fields.map(([name, value]) => (
                                    <div className="pd-spec-row" key={name}><dt>{name}</dt><dd>{value || t("Нет данных")}</dd></div>
                                ))}
                            </dl>
                        </>
                    )}
                    {!characteristics.length && !fields.length && <p className="pd-empty-specs">{messages.noCharacteristics}</p>}
                </section>
            </div>
        </MainDiv>
    );
};

const ProductDetails = ({isOrder}: ProductDetailsProps) => {
    const {id} = useParams<{id: string}>();
    const {data: product, isLoading, isError} = useGetProductByIdQuery(id!, {skip: !id});
    const hasCategoryName = Boolean(product?.categoryName || product?.category?.name);
    const {data: category} = useGetCategoryByIdQuery(product?.categoryId ?? "", {skip: !product || hasCategoryName});
    const {t} = useTranslation();

    if (isLoading) return <Loader/>;
    if (isError || !product) return (
        <MainDiv><EmptyState><strong>{t("Продукт не загружен")}</strong>
            <span>{t("Проверьте ID продукта или попробуйте позже.")}</span></EmptyState></MainDiv>
    );

    return <><ProductDetailsView key={product.id} product={product} categoryName={category?.name} isOrder={isOrder}/><ReceiptPricingProductStage productId={product.id}/><CatalogCostCard itemType={0} itemId={product.id}/></>;
};

export default ProductDetails;
